import{_ as o}from"./chunks/login-page.DiTLb9-p.js";import{_ as r,c as a,o as e,ae as n}from"./chunks/framework.CDjunVez.js";const s="/assets/portal_cn.SO_8WMh7.png",l="/assets/desk.FUyJP2ub.png",q=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"quick-start.md","filePath":"quick-start.md","lastUpdated":1766459798000}'),i={name:"quick-start.md"};function d(g,t,c,h,p,u){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>欢迎使用 <strong>Owl Eye (OE) 枭眼预警平台</strong>！本指南将帮助您在 <strong>2 分钟内完成首次登录并开始使用核心功能</strong>。</p><h2 id="_1-访问系统" tabindex="-1">1. 访问系统 <a class="header-anchor" href="#_1-访问系统" aria-label="Permalink to &quot;1. 访问系统&quot;">​</a></h2><p>在公司内网环境中，打开浏览器（推荐使用 Chrome），访问以下地址：<br><a href="https://owleye.envision-energy.com/#/" target="_blank" rel="noreferrer">https://owleye.envision-energy.com/#/</a></p><blockquote><p>💡 <strong>提示</strong></p><ul><li>若无法打开，请确认您已连接公司内网（或通过 VPN 接入）。</li><li>VPN 账号申请及客户端安装，请通过企业微信联系 IT Helpdesk 服务台。</li></ul></blockquote><h2 id="_2-登录账号" tabindex="-1">2. 登录账号 <a class="header-anchor" href="#_2-登录账号" aria-label="Permalink to &quot;2. 登录账号&quot;">​</a></h2><ol><li>在登录页面输入您的 <strong>OA 账号</strong>（通常为邮箱前缀，如 <code>san.zhang</code>）和密码。</li><li>点击 <strong>【登录】</strong> 按钮。</li></ol><p><img src="'+o+'" alt="系统登录页面"></p><blockquote><p>🔐 <strong>安全说明</strong></p><ul><li>若忘记密码，请通过企业微信联系 IT Helpdesk 服务台重置。</li></ul></blockquote><h2 id="_3-选择区域站点" tabindex="-1">3. 选择区域站点 <a class="header-anchor" href="#_3-选择区域站点" aria-label="Permalink to &quot;3. 选择区域站点&quot;">​</a></h2><p>成功登录后，您将进入 <strong>OE 站点选择门户（Portal）</strong>。请根据业务归属选择对应站点：</p><ul><li><strong>全球站点（Global）</strong>：适用于除印度以外的所有国家/地区</li><li><strong>印度站点（India）</strong>：仅适用于印度区域</li></ul><p>点击 <strong>【Go】</strong> 按钮，系统将自动跳转至所选区域。</p><blockquote><p>🔒 <strong>数据隔离说明</strong><br> 根据 IT 信息安全政策，印度站点与全球站点数据完全隔离，无法相互访问。</p></blockquote><p><img src="'+s+'" alt="Portal 站点选择页"></p><h2 id="_4-首次登录-权限确认" tabindex="-1">4. 首次登录：权限确认 <a class="header-anchor" href="#_4-首次登录-权限确认" aria-label="Permalink to &quot;4. 首次登录：权限确认&quot;">​</a></h2><p>首次使用前，请确认已完成系统权限开通（仅需一次）：</p><ul><li><strong>预警接收人 / 行动项处理人</strong>：系统通常会自动授权。如提示无权限，请联系业务负责人确认。</li><li><strong>片区负责人 / 业务负责人 / 合规委员</strong>：系统默认已开通权限；若人员变更，请联系产品团队更新配置。</li></ul><blockquote><p>✅ 权限确认完成后，您将进入 <strong>工作台首页</strong>。</p></blockquote><p><img src="'+l+'" alt="工作台首页"></p><h2 id="_5-开始使用核心功能" tabindex="-1">5. 开始使用核心功能 <a class="header-anchor" href="#_5-开始使用核心功能" aria-label="Permalink to &quot;5. 开始使用核心功能&quot;">​</a></h2><p>根据您的角色，重点关注以下模块：</p><table tabindex="0"><thead><tr><th>角色</th><th>推荐操作</th></tr></thead><tbody><tr><td><strong>预警接收人员、行动项处理人员</strong></td><td>首页 → 处理 “待确认预警项” 或 “待完成行动项”</td></tr><tr><td><strong>片区管理人员</strong></td><td>应用中心 → 选择对应“应用模块” → 完成预警复核管理</td></tr><tr><td><strong>应用管理人员</strong></td><td>应用中心 → 选择对应“应用模块” → 进行预警导出与分析</td></tr><tr><td><strong>模型开发人员</strong></td><td>应用中心 → 选择“试运行模块” → 查询试运行结果</td></tr></tbody></table><h2 id="_6-获取帮助" tabindex="-1">6. 获取帮助 <a class="header-anchor" href="#_6-获取帮助" aria-label="Permalink to &quot;6. 获取帮助&quot;">​</a></h2><ul><li><strong>常见问题</strong>：参见 <a href="/faq">FAQ 文档</a></li><li><strong>业务支持</strong>：请联系对应业务负责人</li><li><strong>系统支持</strong>：倪炜伦 (<code>weilun.ni1</code>)、范赟桢 (<code>yunzhen.fan</code>)</li></ul><blockquote><p>⚠️ <strong>重要提醒</strong><br> 本系统处理敏感业务数据，请严格遵守公司《数据安全管理办法》。<br><strong>禁止截图、外传或非授权访问</strong>。</p></blockquote>',26)])])}const k=r(i,[["render",d]]);export{q as __pageData,k as default};
